/**
 * The rules every stored file follows, in both URL modes (presigned S3 in production, signed dev
 * routes locally). Pure; shared by the token, the URL builder and the routes.
 *
 * - Only images: an uploaded `text/html` or SVG served back from our origin would run script next to
 *   the admin cookie (stored XSS).
 * - Keys are generated by server code under a known prefix, never derived from a user's filename
 *   (filenames are metadata in D1). The charset is URL-safe, so a key is never percent-encoded.
 */

export const MEDIA_TYPES = ['image/jpeg', 'image/png', 'image/webp'] as const;
export type MediaType = (typeof MEDIA_TYPES)[number];

export function isMediaType(value: unknown): value is MediaType {
  return typeof value === 'string' && (MEDIA_TYPES as readonly string[]).includes(value);
}

/** The first segment of every key. `dev` is for local probes and tests. */
export const BLOB_PREFIXES = ['galleries', 'branding', 'dev'] as const;

/** The largest upload accepted through a presigned URL (checked when minting; Phase 5 re-checks the stored size). */
export const MAX_UPLOAD_BYTES = 100 * 1024 * 1024;
/** The development routes buffer the body in memory (OpenNext does too): keep it small. */
export const MAX_DEV_UPLOAD_BYTES = 32 * 1024 * 1024;

const KEY_RE = /^[a-z0-9._/-]{1,512}$/;

/** A key we may store under: lower-case URL-safe characters, a known first segment, no empty/dot segments. */
export function isBlobKey(key: unknown): key is string {
  if (typeof key !== 'string' || !KEY_RE.test(key)) return false;
  const segments = key.split('/');
  if (!(BLOB_PREFIXES as readonly string[]).includes(segments[0] ?? '')) return false;
  return segments.length > 1 && segments.every((s) => s !== '' && s !== '.' && s !== '..');
}

const MAX_FILENAME = 150;

/**
 * An attachment `Content-Disposition` for a download name: an ASCII `filename` (unsafe characters
 * replaced) plus the exact name as RFC 5987 `filename*`. Nothing from the name can break the header.
 */
export function contentDisposition(name: string): string {
  const clean = Array.from(name.normalize('NFC'))
    .filter((c) => c >= ' ' && c !== '\u007f')
    .join('')
    .replace(/[/\\]/g, '_')
    .trim()
    .slice(0, MAX_FILENAME);
  const safe = clean || 'download';
  const ascii = safe.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  const encoded = encodeURIComponent(safe).replace(/['()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encoded}`;
}
